import { useEffect, useRef, useState } from "react";

const clients = [
  { name: "Lokmanya Hospitals", logo: "https://lokmanyahospitals.com/_next/image?url=%2Fimages%2Fnew-theme%2Flokmanya-new-png-logo.webp&w=640&q=75" },
  { name: "Company Two",        logo: "https://framerusercontent.com/images/1GnnFaZyqduCKJHAF10bMHGcAGc.svg?width=152&height=44" },
  { name: "Company Three",      logo: "data:image/png;base64," },
  // { name: "Company Four",      logo: "https://scontent.fpnq12-1.fna.fbcdn.net/v/t39.30808-6/269777922_443458330766137_3450855557130953903_n.jpg?_nc_cat=104&ccb=1-7&_nc_sid=1d70fc&_nc_ohc=LqCvqDgNSFsQ7kNvwGZznnp&_nc_oc=AdqBOQODaw90jYD3ho6O_10fLQspszvNr1i4PfiO7r44o61eJozYv_YRhArnPmyxI30&_nc_zt=23&_nc_ht=scontent.fpnq12-1.fna&_nc_gid=skN71h6_AZbTIQVc1weSLA&_nc_ss=7b289&oh=00_Af4YJuBYxJZp7u9LIy_d_2J9mCWdRvv0nbxZKw9MOypZTg&oe=6A08A289" },
  { name: "Company Five",     logo: "https://pbs.twimg.com/profile_images/1605844245776334848/CUIZlzys_400x400.jpg" },
  { name: "Company Six",      logo: "https://content.jdmagicbox.com/v2/comp/mumbai/03/022p5424403/catalogue/arihant-capital-markets-ltd-borivali-west-mumbai-share-brokers-0brmfsgcpb.jpg" },
];

// Duplicate for seamless looping
const DOUBLED = [...clients, ...clients];

// Card width + gap in px
const CARD_W   = 180;
const CARD_GAP = 20;
const STEP     = CARD_W + CARD_GAP;   // px per card slot
const SPEED    = 0.5;                  // px per animation frame (~30px/s at 60fps)

export default function OurClients() {
  const trackRef  = useRef(null);
  const rafRef    = useRef(null);
  const offsetRef = useRef(0);         // current translateX (negative)
  const pausedRef = useRef(false);

  // Total width of one set of cards (original, not doubled)
  const totalOneSet = clients.length * STEP;

  const animate = () => {
    if (!pausedRef.current && trackRef.current) {
      offsetRef.current -= SPEED;
      // Reset seamlessly when we've scrolled one full set
      if (Math.abs(offsetRef.current) >= totalOneSet) {
        offsetRef.current += totalOneSet;
      }
      trackRef.current.style.transform = `translateX(${offsetRef.current}px)`;
    }
    rafRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    rafRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  const pause = () => { pausedRef.current = true; };
  const resume = () => { pausedRef.current = false; };

  return (
    <section
      aria-labelledby="clients-heading"
      style={{
        padding: "clamp(28px,6vw,56px) 0",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: 900,
        margin: "0 auto",
      }}
    >
      {/* Heading */}
      <div style={{ textAlign: "center", padding: "0 16px", marginBottom: "clamp(20px,4vw,36px)" }}>
        <h2
          id="clients-heading"
          style={{
            fontWeight: 700,
            fontSize: "clamp(18px,5vw,26px)",
            color: "#1a1a1a",
            margin: "0 0 6px",
            fontFamily: "Georgia",
          }}
        >
          Our Trusted Clients
        </h2>
        <p style={{ color: "#666", fontSize: "clamp(12px,3.5vw,14px)", margin: "0 0 12px" }}>
          Brands that trust BNS Holidays for their travel needs
        </p>
        <div style={{ width: 48, height: 3, background: "#2a3faa", borderRadius: 2, margin: "0 auto" }} />
      </div>

      {/* Fade masks on left/right edges */}
      <div style={{ position: "relative", overflow: "hidden" }}>
        <div style={{
          position: "absolute", left: 0, top: 0, bottom: 0, width: 80, zIndex: 2,
          background: "linear-gradient(to right, #fff 0%, transparent 100%)",
          pointerEvents: "none",
        }} />
        <div style={{
          position: "absolute", right: 0, top: 0, bottom: 0, width: 80, zIndex: 2,
          background: "linear-gradient(to left, #fff 0%, transparent 100%)",
          pointerEvents: "none",
        }} />

        {/* Scrolling track */}
        <div
          style={{ overflow: "hidden", padding: "8px 0" }}
          onMouseEnter={pause}
          onMouseLeave={resume}
          onTouchStart={pause}
          onTouchEnd={resume}
        >
          <div
            ref={trackRef}
            style={{
              display: "flex",
              gap: CARD_GAP,
              willChange: "transform",
              width: "max-content",
            }}
          >
            {DOUBLED.map(({ name, logo }, i) => (
              <div
                key={`${name}-${i}`}
                style={{
                  flexShrink: 0,
                  width: CARD_W,
                  height: 110,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  // border: "1px solid #e8e8e8",
                  borderRadius: 12,
                  background: "#fff",
                  boxShadow: "0 2px 8px rgba(0,0,0,0.06)",
                  overflow: "hidden",
                  padding: "14px 16px",
                  boxSizing: "border-box",
                }}
              >
                <img
                  src={logo}
                  alt={`${name} logo`}
                  loading="lazy"
                  style={{
                    maxWidth: "100%",
                    maxHeight: "100%",
                    objectFit: "contain",
                    display: "block",
                  }}
                />
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}